def max_frequency(nums, k):
    n = len(nums)
    nums = sorted(nums)
    best = 1
    for right in range(n):
        for left in range(right + 1):
            window_size = right - left + 1
            target_sum = nums[right] * window_size
            current_sum = sum(nums[left:right + 1])
            cost = target_sum - current_sum                                   # ops needed to raise every element up to nums[right]
            if cost <= k:
                best = max(best, window_size)
                break                                                          # any smaller left within budget is already covered by a larger left
    return best


if __name__ == "__main__":
    print(max_frequency([1, 4, 8, 13], 5))

