import java.util.*;

public class Main {
    int maxFrequency(int[] nums, int k) {
        int n = nums.length;
        Arrays.sort(nums);
        int best = 1;
        for (int right = 0; right < n; right++) {
            for (int left = right; left >= 0; left--) {
                int windowSize = right - left + 1;
                long targetSum = (long) nums[right] * windowSize;
                long currentSum = 0;
                for (int i = left; i <= right; i++) currentSum += nums[i];
                long cost = targetSum - currentSum;                                  // ops needed to raise every element up to nums[right]
                if (cost <= k) {
                    best = Math.max(best, windowSize);
                } else {
                    break;                                                            // a smaller (further left) window only costs more, not less
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxFrequency(new int[]{1, 4, 8, 13}, 5));
    }
}

