int maxFrequency(vector<int>& nums, int k) {
    int n = (int)nums.size();
    sort(nums.begin(), nums.end());
    int best = 1;
    for (int right = 0; right < n; right++) {
        long long currentSum = 0;
        for (int left = right; left >= 0; left--) {
            currentSum += nums[left];
            int windowSize = right - left + 1;
            long long targetSum = (long long) nums[right] * windowSize;
            long long cost = targetSum - currentSum;                              // ops needed to raise every element up to nums[right]
            if (cost <= k) {
                best = max(best, windowSize);
            } else {
                break;                                                              // a smaller (further left) window only costs more, not less
            }
        }
    }
    return best;
}

