import java.util.*;

public class Main {
    int maxFrequency(int[] nums, int k) {
        Arrays.sort(nums);                                                        // equal values must sit together, so the window can only be a sorted stretch
        int left = 0;
        long windowSum = 0;
        int best = 1;
        for (int right = 0; right < nums.length; right++) {
            windowSum += nums[right];
            while ((long) nums[right] * (right - left + 1) - windowSum > k) {
                windowSum -= nums[left];                                           // too costly to raise everyone up to nums[right], shrink from the left
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxFrequency(new int[]{1, 4, 8, 13}, 5));
    }
}

